--
-- Name: v_ekonomi_kategori_summary; Type: VIEW; Schema: public; Owner: user
--

CREATE VIEW public.v_ekonomi_kategori_summary AS
 SELECT jenis_usaha AS kategori,
    count(*) AS jumlah,
    count(
        CASE
            WHEN ((status)::text = 'aktif'::text) THEN 1
            ELSE NULL::integer
        END) AS aktif,
    count(
        CASE
            WHEN ((status)::text = 'pending'::text) THEN 1
            ELSE NULL::integer
        END) AS pending,
    count(
        CASE
            WHEN ((status)::text = 'nonaktif'::text) THEN 1
            ELSE NULL::integer
        END) AS nonaktif
   FROM public.umkm u
  WHERE (jenis_usaha IS NOT NULL)
  GROUP BY jenis_usaha
  ORDER BY (count(*)) DESC;


ALTER VIEW public.v_ekonomi_kategori_summary OWNER TO "user";

--
-- Name: v_pembangunan_anggaran_tahun; Type: VIEW; Schema: public; Owner: user
--

CREATE VIEW public.v_pembangunan_anggaran_tahun AS
 SELECT tahun_anggaran AS tahun,
    count(id) AS jumlah_proyek,
    sum(pagu_anggaran) AS total_pagu,
    sum(realisasi_anggaran) AS total_realisasi
   FROM public.pembangunan_desa pd
  WHERE (tahun_anggaran IS NOT NULL)
  GROUP BY tahun_anggaran
  ORDER BY tahun_anggaran DESC;


ALTER VIEW public.v_pembangunan_anggaran_tahun OWNER TO "user";

